import re
from dataclasses import dataclass
from datetime import datetime

SENSOR_ID = re.compile(r'^[A-D]-[A-Z]{1,3}\d{2}$')


@dataclass(frozen=True)
class Reading:
    sensor_id: str
    ts: datetime
    kind: str
    value: float

    def __post_init__(self):
        if not SENSOR_ID.match(self.sensor_id):
            raise ValueError(f'bad sensor id {self.sensor_id}')

