from pathlib import Path

import pyarrow as pa
import pyarrow.parquet as pq


def write_day(root, day, rows):
    path = Path(root) / f'day={day.isoformat()}' / 'readings.parquet'
    path.parent.mkdir(parents=True, exist_ok=True)
    pq.write_table(pa.Table.from_pylist(rows), path)


def read_range(root, start, end, columns=None):
    days = [p for p in Path(root).glob('day=*') if start.isoformat() <= p.name[4:] <= end.isoformat()]
    return pa.concat_tables([pq.read_table(p, columns=columns) for p in sorted(days)])

