MAX_GAP_MIN = 15


def fill(series: pd.Series) -> pd.Series:
    s = series.resample('1min').mean()
    return s.interpolate(limit=MAX_GAP_MIN, limit_area='inside')

import pandas as pd

MAX_GAP_MIN = 15


def fill(series: pd.Series) -> pd.DataFrame:
    s = series.resample('1min').mean()
    filled = s.interpolate(limit=MAX_GAP_MIN, limit_area='inside')
    return pd.DataFrame({'value': filled, 'filled': s.isna() & filled.notna()})

