def hourly(df):
    g = df.set_index('ts').groupby(['zone', 'kind']).resample('1h')['value']
    return g.agg(['mean', 'min', 'max']).reset_index()

def hourly(df):
    g = df.set_index('ts').groupby(['zone', 'kind']).resample('1h')
    out = g['value'].agg(['mean']).reset_index()
    measured = df[~df['filled']].set_index('ts').groupby(['zone', 'kind']).resample('1h')['value']
    extremes = measured.agg(['min', 'max']).reset_index()
    return out.merge(extremes, on=['zone', 'kind', 'ts'], how='left')

