def daily(hourly_df, areas):
    df = hourly_df.assign(day=hourly_df['ts'].dt.date, area=hourly_df['zone'].map(areas))
    df['weighted'] = df['mean'] * df['area']
    g = df.groupby(['greenhouse', 'kind', 'day'])
    return (g['weighted'].sum() / g['area'].sum()).rename('mean').reset_index()

